#!/bin/bash
# bnet-paste: Wolf types pasted text as Ctrl+Shift+U <hex digits> (GTK Unicode input), which Wine ignores.
# Sway catches that sequence (bindings generated by startup.sh) and appends the keys to $S/cur, one
# character per space-separated hex number. Half a second after the last key this script puts the
# text on the clipboard and sends Ctrl+V to the focused window.
S=/tmp/bnet-paste
export LC_ALL=C.UTF-8
export DISPLAY="${DISPLAY:-:0}"
export SWAYSOCK="${SWAYSOCK:-/run/user/wolf/sway.socket}"
case "$1" in
    arm)
        gen=$(date +%s%N); echo "$gen" > "$S/gen"
        ( sleep 0.5; [ "$(cat "$S/gen")" = "$gen" ] && exec "$0" finish ) > /dev/null 2>&1 &
        ;;
    finish)
        swaymsg mode default > /dev/null 2>&1
        cp "$S/cur" "$S/cur.done"; : > "$S/cur"
        : > "$S/paste"
        for hex in $(cat "$S/cur.done"); do
            # shellcheck disable=SC2059
            printf "\\U$(printf '%08x' "0x$hex")" >> "$S/paste"
        done
        [ -s "$S/paste" ] || exit 0
        xclip -selection clipboard -i < "$S/paste"
        sleep 0.1
        xdotool key --clearmodifiers ctrl+v
        ;;
esac
exit 0
